#!/usr/bin/env python3
"""Generate Active Satellites in Earth Orbit - 2026 Catalog Analysis Report"""

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
from matplotlib.gridspec import GridSpec
import base64
from io import BytesIO
import json
from datetime import datetime

# Read data
df = pd.read_csv('/app/benchmark/data.csv')

# Data preprocessing
df['ECCENTRICITY'] = pd.to_numeric(df['ECCENTRICITY'], errors='coerce').fillna(0)
df['MEAN_MOTION_DOT'] = pd.to_numeric(df['MEAN_MOTION_DOT'], errors='coerce').fillna(0)
df['BSTAR'] = pd.to_numeric(df['BSTAR'], errors='coerce').fillna(0)

# Extract launch year from OBJECT_ID
df['LAUNCH_YEAR'] = df['OBJECT_ID'].str[:4].astype(int)

# Orbit classification based on MEAN_MOTION thresholds
# LEO: >14 rev/day, GEO: ~1.0 rev/day, MEO: between, HEO: highly eccentric or unusual
def classify_orbit(row):
    mm = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY']
    if mm > 14:
        return 'LEO'
    elif mm >= 0.9 and mm <= 1.1:
        return 'GEO'
    elif mm > 1.1 and mm <= 14:
        return 'MEO'
    else:
        return 'HEO'

df['ORBIT_REGIME'] = df.apply(classify_orbit, axis=1)

# Constellation identification from OBJECT_NAME prefixes
def identify_constellation(name):
    name_upper = str(name).upper()
    if name_upper.startswith('STARLINK'):
        return 'Starlink'
    elif name_upper.startswith('ONEWEB'):
        return 'OneWeb'
    elif 'IRIDIUM' in name_upper:
        return 'Iridium'
    elif 'GPS' in name_upper:
        return 'GPS'
    elif 'GLONASS' in name_upper:
        return 'GLONASS'
    elif 'GALILEO' in name_upper:
        return 'Galileo'
    elif 'BEIDOU' in name_upper:
        return 'BeiDou'
    elif 'SWARM' in name_upper:
        return 'Swarm'
    elif 'SES' in name_upper:
        return 'SES'
    elif 'INTELSAT' in name_upper:
        return 'Intelsat'
    elif 'EUTELSAT' in name_upper:
        return 'Eutelsat'
    elif ' Telesat' in name_upper or 'TELESAT' in name_upper:
        return 'Telesat'
    elif 'ORBCOMM' in name_upper:
        return 'Orbcomm'
    elif 'HUBBLE' in name_upper or 'HST' in name_upper:
        return 'Hubble'
    elif 'ISS' in name_upper:
        return 'ISS'
    elif 'COSMOS' in name_upper or 'COSMOS ' in name_upper:
        return 'Cosmos'
    elif 'YAMAL' in name_upper:
        return 'Yamal'
    elif 'YAOGAN' in name_upper:
        return 'Yaogan'
    elif 'FENGYUN' in name_upper:
        return 'Fengyun'
    elif 'METEOR' in name_upper:
        return 'Meteor'
    else:
        return 'Other'

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(identify_constellation)

# Calculate KPIs
total_satellites = len(df)
leo_count = len(df[df['ORBIT_REGIME'] == 'LEO'])
leo_share = (leo_count / total_satellites) * 100
starlink_count = len(df[df['CONSTELLATION'] == 'Starlink'])
median_inclination = df['INCLINATION'].median()
post_2020_count = len(df[df['LAUNCH_YEAR'] >= 2020])

# Top operators
constellation_counts = df['CONSTELLATION'].value_counts()

# Per-regime breakdown
regime_counts = df['ORBIT_REGIME'].value_counts()

# Epoch range
df['EPOCH_DT'] = pd.to_datetime(df['EPOCH'], errors='coerce')
epoch_min = df['EPOCH_DT'].min().strftime('%Y-%m-%d')
epoch_max = df['EPOCH_DT'].max().strftime('%Y-%m-%d')

# Launch year statistics
year_counts = df['LAUNCH_YEAR'].value_counts().sort_index()

print("=== DATA ANALYSIS COMPLETE ===")
print(f"Total satellites: {total_satellites}")
print(f"LEO count: {leo_count} ({leo_share:.1f}%)")
print(f"Starlink count: {starlink_count}")
print(f"Median inclination: {median_inclination:.2f}°")
print(f"Post-2020 launches: {post_2020_count}")
print(f"Epoch range: {epoch_min} to {epoch_max}")
print(f"\nOrbit regime distribution:\n{regime_counts}")
print(f"\nTop 10 operators:\n{constellation_counts.head(10)}")

# Generate charts as base64
def generate_chart(chart_func, figsize=(10, 6)):
    plt.style.use('seaborn-v0_8-whitegrid')
    fig = chart_func(figsize)
    buf = BytesIO()
    plt.savefig(buf, format='png', bbox_inches='tight', dpi=150, facecolor='white')
    buf.seek(0)
    img_b64 = base64.b64encode(buf.getvalue()).decode()
    plt.close()
    return img_b64

def chart_launch_trends(figsize):
    fig, ax = plt.subplots(figsize=figsize)

    # Filter to 2000+ for better visibility of recent trends
    df_recent = df[df['LAUNCH_YEAR'] >= 2000]
    year_counts_recent = df_recent['LAUNCH_YEAR'].value_counts().sort_index()

    bars = ax.bar(year_counts_recent.index, year_counts_recent.values,
                  color='#2E86AB', edgecolor='white', linewidth=0.5)

    # Highlight post-2020
    for bar, year in zip(bars, year_counts_recent.index):
        if year >= 2020:
            bar.set_color('#E94F37')

    ax.set_xlabel('Launch Year', fontsize=12, fontweight='bold')
    ax.set_ylabel('Number of Active Satellites', fontsize=12, fontweight='bold')
    ax.set_title('Launch Year Trends: Active Satellites by Launch Year (2000–2026)',
                 fontsize=14, fontweight='bold', pad=15)

    # Add value labels on bars for recent years
    for i, (year, count) in enumerate(zip(year_counts_recent.index, year_counts_recent.values)):
        if year >= 2018:
            ax.annotate(f'{count:,}', xy=(year, count), ha='center', va='bottom',
                       fontsize=8, fontweight='bold')

    ax.set_xlim(1999.5, 2026.5)
    plt.xticks(rotation=45)
    fig.tight_layout()
    return fig

def chart_orbit_regime(figsize):
    fig, ax = plt.subplots(figsize=figsize)

    colors = {'LEO': '#2E86AB', 'MEO': '#A23B72', 'GEO': '#F18F01', 'HEO': '#C73E1D'}
    regime_order = ['LEO', 'MEO', 'GEO', 'HEO']
    counts = [regime_counts.get(r, 0) for r in regime_order]
    color_list = [colors[r] for r in regime_order]

    wedges, texts, autotexts = ax.pie(counts, labels=regime_order, autopct='%1.1f%%',
                                       colors=color_list, startangle=90,
                                       explode=[0.05, 0, 0, 0], shadow=True)

    for autotext in autotexts:
        autotext.set_fontsize(11)
        autotext.set_fontweight('bold')
        autotext.set_color('white')

    ax.set_title('Orbital Regime Distribution', fontsize=14, fontweight='bold', pad=15)
    return fig

def chart_constellation_breakdown(figsize):
    fig, ax = plt.subplots(figsize=figsize)

    top_n = 15
    top_constellations = constellation_counts.head(top_n)
    colors = plt.cm.viridis(np.linspace(0.2, 0.8, top_n))

    bars = ax.barh(range(len(top_constellations)), top_constellations.values, color=colors)
    ax.set_yticks(range(len(top_constellations)))
    ax.set_yticklabels(top_constellations.index)
    ax.invert_yaxis()

    ax.set_xlabel('Number of Active Satellites', fontsize=12, fontweight='bold')
    ax.set_title(f'Top {top_n} Satellite Operators/Constellations', fontsize=14, fontweight='bold', pad=15)

    # Add value labels
    for i, (count, name) in enumerate(zip(top_constellations.values, top_constellations.index)):
        ax.text(count + 50, i, f'{count:,}', va='center', fontsize=9)

    # Annotate Starlink dominance
    if 'Starlink' in top_constellations.index:
        starlink_pos = list(top_constellations.index).index('Starlink')
        ax.annotate('Starlink dominates\nwith 40%+ of all active satellites',
                   xy=(top_constellations['Starlink'], starlink_pos),
                   xytext=(top_constellations['Starlink']*0.6, starlink_pos + 3),
                   fontsize=10, color='#E94F37', fontweight='bold',
                   arrowprops=dict(arrowstyle='->', color='#E94F37', lw=1.5))

    ax.set_xlim(0, top_constellations.values[0] * 1.15)
    plt.tight_layout()
    return fig

def chart_inclination_distribution(figsize):
    fig, ax = plt.subplots(figsize=figsize)

    # LEO only for inclination analysis
    leo_df = df[df['ORBIT_REGIME'] == 'LEO']

    ax.hist(leo_df['INCLINATION'], bins=50, color='#2E86AB', edgecolor='white', alpha=0.8)
    ax.axvline(median_inclination, color='#E94F37', linestyle='--', linewidth=2,
               label=f'Median: {median_inclination:.1f}°')

    ax.set_xlabel('Inclination (degrees)', fontsize=12, fontweight='bold')
    ax.set_ylabel('Number of Satellites', fontsize=12, fontweight='bold')
    ax.set_title('LEO Inclination Distribution', fontsize=14, fontweight='bold', pad=15)
    ax.legend(fontsize=10)

    # Add annotation for common inclinations
    ax.annotate('Most LEO satellites fly at\nlow-to-moderate inclinations', xy=(53, 3000),
               fontsize=10, ha='center', style='italic', color='#555')

    return fig

def chart_mean_motion_distribution(figsize):
    fig, ax = plt.subplots(figsize=figsize)

    ax.hist(df['MEAN_MOTION'], bins=100, color='#2E86AB', edgecolor='white', alpha=0.7)

    ax.axvline(14, color='#E94F37', linestyle='--', linewidth=2, label='LEO threshold (>14)')
    ax.axvline(1.0, color='#F18F01', linestyle='--', linewidth=2, label='GEO (~1.0)')

    ax.set_xlabel('Mean Motion (revolutions/day)', fontsize=12, fontweight='bold')
    ax.set_ylabel('Number of Satellites', fontsize=12, fontweight='bold')
    ax.set_title('Mean Motion Distribution (Orbit Height Indicator)', fontsize=14, fontweight='bold', pad=15)
    ax.legend(fontsize=10, loc='upper right')
    ax.set_xlim(0, 16)

    return fig

def chart_eccentricity_distribution(figsize):
    fig, ax = plt.subplots(figsize=figsize)

    # Filter to reasonable range for visualization
    ecc_filtered = df[df['ECCENTRICITY'] < 0.3]['ECCENTRICITY']

    ax.hist(ecc_filtered, bins=50, color='#A23B72', edgecolor='white', alpha=0.8)
    ax.axvline(ecc_filtered.median(), color='#E94F37', linestyle='--', linewidth=2,
               label=f'Median: {ecc_filtered.median():.4f}')

    ax.set_xlabel('Eccentricity', fontsize=12, fontweight='bold')
    ax.set_ylabel('Number of Satellites', fontsize=12, fontweight='bold')
    ax.set_title('Eccentricity Distribution (Orbit Shape)', fontsize=14, fontweight='bold', pad=15)
    ax.legend(fontsize=10)

    return fig

def chart_starlink_growth(figsize):
    fig, ax = plt.subplots(figsize=figsize)

    starlink_df = df[df['CONSTELLATION'] == 'Starlink']
    starlink_years = starlink_df['LAUNCH_YEAR'].value_counts().sort_index()

    bars = ax.bar(starlink_years.index, starlink_years.values, color='#2E86AB', edgecolor='white')
    ax.set_xlabel('Launch Year', fontsize=12, fontweight='bold')
    ax.set_ylabel('Starlink Satellites Launched', fontsize=12, fontweight='bold')
    ax.set_title('Starlink Constellation Growth Over Time', fontsize=14, fontweight='bold', pad=15)

    # Add value labels
    for bar, count in zip(bars, starlink_years.values):
        ax.annotate(f'{count:,}', xy=(bar.get_x() + bar.get_width()/2, count),
                   ha='center', va='bottom', fontsize=8, fontweight='bold')

    plt.xticks(rotation=45)
    fig.tight_layout()
    return fig

# Generate all charts
print("\nGenerating charts...")
charts = {
    'launch_trends': generate_chart(chart_launch_trends),
    'orbit_regime': generate_chart(chart_orbit_regime),
    'constellation': generate_chart(chart_constellation_breakdown),
    'inclination': generate_chart(chart_inclination_distribution),
    'mean_motion': generate_chart(chart_mean_motion_distribution),
    'eccentricity': generate_chart(chart_eccentricity_distribution),
    'starlink_growth': generate_chart(chart_starlink_growth)
}
print("Charts generated successfully!")

# Build HTML report
html_content = f'''<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Active Satellites in Earth Orbit — 2026 Catalog Analysis</title>
    <style>
        * {{
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }}

        body {{
            font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, sans-serif;
            line-height: 1.6;
            color: #333;
            background: #f5f7fa;
        }}

        .container {{
            max-width: 1200px;
            margin: 0 auto;
            padding: 20px;
        }}

        header {{
            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
            color: white;
            padding: 40px 20px;
            margin-bottom: 30px;
        }}

        header h1 {{
            font-size: 2rem;
            font-weight: 600;
            margin-bottom: 10px;
        }}

        header .subtitle {{
            font-size: 1rem;
            opacity: 0.8;
        }}

        .kpi-section {{
            background: white;
            border-radius: 12px;
            padding: 25px;
            margin-bottom: 30px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.08);
        }}

        .kpi-grid {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 20px;
        }}

        .kpi-card {{
            text-align: center;
            padding: 20px;
            background: #f8f9fa;
            border-radius: 8px;
            border-left: 4px solid #2E86AB;
        }}

        .kpi-card.highlight {{
            border-left-color: #E94F37;
            background: #fff5f5;
        }}

        .kpi-value {{
            font-size: 2rem;
            font-weight: 700;
            color: #1a1a2e;
        }}

        .kpi-card.highlight .kpi-value {{
            color: #E94F37;
        }}

        .kpi-label {{
            font-size: 0.85rem;
            color: #666;
            margin-top: 5px;
        }}

        .section {{
            background: white;
            border-radius: 12px;
            padding: 30px;
            margin-bottom: 30px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.08);
        }}

        .section h2 {{
            font-size: 1.4rem;
            color: #1a1a2e;
            margin-bottom: 20px;
            padding-bottom: 10px;
            border-bottom: 2px solid #2E86AB;
        }}

        .section h3 {{
            font-size: 1.1rem;
            color: #333;
            margin: 20px 0 10px 0;
        }}

        .chart-container {{
