#!/usr/bin/env python3
"""Generate Active Satellites in Earth Orbit - 2026 Catalog Analysis Report"""

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
from matplotlib.gridspec import GridSpec
import base64
from io import BytesIO
import json
from datetime import datetime

# Read data
df = pd.read_csv('/app/benchmark/data.csv')

# Data preprocessing
df['ECCENTRICITY'] = pd.to_numeric(df['ECCENTRICITY'], errors='coerce').fillna(0)
df['MEAN_MOTION_DOT'] = pd.to_numeric(df['MEAN_MOTION_DOT'], errors='coerce').fillna(0)
df['BSTAR'] = pd.to_numeric(df['BSTAR'], errors='coerce').fillna(0)

# Extract launch year from OBJECT_ID
df['LAUNCH_YEAR'] = df['OBJECT_ID'].str[:4].astype(int)

# Orbit classification based on MEAN_MOTION thresholds
# LEO: >14 rev/day, GEO: ~1.0 rev/day, MEO: between, HEO: highly eccentric or unusual
def classify_orbit(row):
    mm = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY']
    if mm > 14:
        return 'LEO'
    elif mm >= 0.9 and mm <= 1.1:
        return 'GEO'
    elif mm > 1.1 and mm <= 14:
        return 'MEO'
    else:
        return 'HEO'

df['ORBIT_REGIME'] = df.apply(classify_orbit, axis=1)

# Constellation identification from OBJECT_NAME prefixes
def identify_constellation(name):
    name_upper = str(name).upper()
    if name_upper.startswith('STARLINK'):
        return 'Starlink'
    elif name_upper.startswith('ONEWEB'):
        return 'OneWeb'
    elif 'IRIDIUM' in name_upper:
        return 'Iridium'
    elif 'GPS' in name_upper:
        return 'GPS'
    elif 'GLONASS' in name_upper:
        return 'GLONASS'
    elif 'GALILEO' in name_upper:
        return 'Galileo'
    elif 'BEIDOU' in name_upper:
        return 'BeiDou'
    elif 'SWARM' in name_upper:
        return 'Swarm'
    elif 'SES' in name_upper:
        return 'SES'
    elif 'INTELSAT' in name_upper:
        return 'Intelsat'
    elif 'EUTELSAT' in name_upper:
        return 'Eutelsat'
    elif ' Telesat' in name_upper or 'TELESAT' in name_upper:
        return 'Telesat'
    elif 'ORBCOMM' in name_upper:
        return 'Orbcomm'
    elif 'HUBBLE' in name_upper or 'HST' in name_upper:
        return 'Hubble'
    elif 'ISS' in name_upper:
        return 'ISS'
    elif 'COSMOS' in name_upper or 'COSMOS ' in name_upper:
        return 'Cosmos'
    elif 'YAMAL' in name_upper:
        return 'Yamal'
    elif 'YAOGAN' in name_upper:
        return 'Yaogan'
    elif 'FENGYUN' in name_upper:
        return 'Fengyun'
    elif 'METEOR' in name_upper:
        return 'Meteor'
    else:
        return 'Other'

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(identify_constellation)

# Calculate KPIs
total_satellites = len(df)
leo_count = len(df[df['ORBIT_REGIME'] == 'LEO'])
leo_share = (leo_count / total_satellites) * 100
